import os

for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('.git', 'node_modules', '.codex')]
    for f in files:
        p = os.path.join(root, f)
        print(p)

import os
import sys

sys.path.insert(0, os.path.join(os.getcwd(), ".codex", "skills", "docx"))

from xml.dom import Node  # node type constants
from scripts.document import Document

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

# Canonical CT_RPr child order (ECMA-376) so w:u lands in a schema-valid slot.
RPR_ORDER = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]

doc = Document("quarterly_report_ooxml")
editor = doc["word/document.xml"]
dom = editor.dom


def element_text(elem):
    parts = []
    for t in elem.getElementsByTagName("w:t"):
        for child in t.childNodes:
            if child.nodeType == Node.TEXT_NODE:
                parts.append(child.data)
    return "".join(parts)


def is_headline(elem):
    text = element_text(elem).strip()
    if not text:
        return False
    if not any(ch.isalpha() for ch in text):
        return False
    return text == text.upper()


def ensure_underline(run):
    rpr = None
    for child in run.childNodes:
        if child.nodeType == Node.ELEMENT_NODE and child.tagName == "w:rPr":
            rpr = child
            break
    if rpr is None:
        rpr = dom.createElementNS(W_NS, "w:rPr")
        run.insertBefore(rpr, run.firstChild)
    for child in rpr.childNodes:
        if child.nodeType == Node.ELEMENT_NODE and child.tagName == "w:u":
            return  # already underlined
    u_el = dom.createElementNS(W_NS, "w:u")
    u_el.setAttributeNS(W_NS, "w:val", "single")
    u_pos = RPR_ORDER.index("w:u")
    anchor = None
    for child in rpr.childNodes:
        if child.nodeType == Node.ELEMENT_NODE and child.tagName in RPR_ORDER:
            if RPR_ORDER.index(child.tagName) > u_pos:
                anchor = child
                break
    if anchor is not None:
        rpr.insertBefore(u_el, anchor)
    else:
        rpr.appendChild(u_el)


headlines = []
for para in dom.getElementsByTagName("w:p"):
    if is_headline(para):
        headlines.append(element_text(para).strip())
        for run in para.getElementsByTagName("w:r"):
            ensure_underline(run)

print("Underlined headlines (%d):" % len(headlines))
for h in headlines:
    print(" - " + h)

doc.save()

