"""Task helper: underline every headline paragraph in quarterly_report.docx's
unpacked OOXML content (quarterly_report_ooxml/word/document.xml).

Headlines are identified precisely by their all-caps title text, which is
known from inspection of the document.  For each such paragraph, every run
that carries non-whitespace text receives <w:u w:val="single"/> in its run
properties (inserted after sz/szCs per the OOXML CT_RPr element order)."""

import sys
from xml.dom.minidom import parse

DOCXML = "quarterly_report_ooxml/word/document.xml"

HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def local(elem):
    """Return element's local name (strip namespace prefix)."""
    return elem.tagName.split(":")[-1]


def children(elem):
    """Direct element children."""
    return [n for n in elem.childNodes if n.nodeType == n.ELEMENT_NODE]


def para_text(para):
    """Concatenated text of a paragraph."""
    parts = []
    for node in para.getElementsByTagNameNS(W_NS, "t") + para.getElementsByTagName("w:t"):
        if node.firstChild is not None:
            parts.append(node.firstChild.data)
    return "".join(parts)


def run_has_text(run):
    """True if the run directly contains a w:t with non-whitespace data."""
    for node in children(run):
        if local(node) == "t" and node.firstChild is not None:
            if node.firstChild.data.strip():
                return True
    return False


def ensure_underline(run):
    """Add <w:u w:val='single'/> to the run's rPr when missing."""
    rprs = [c for c in children(run) if local(c) == "rPr"]
    if not rprs:
        return False
    rpr = rprs[0]
    if any(local(c) == "u" for c in children(rpr)):
        return False
    u = rpr.ownerDocument.createElementNS(W_NS, "w:u")
    u.setAttribute("w:val", "single")
    # CT_RPr order: ... sz, szCs, highlight, u ... -> insert after sz/szCs/
    # highlight so the run properties stay schema-valid.
    idx = -1
    names = {local(c) for c in children(rpr)}
    for i, c in enumerate(children(rpr)):
        if local(c) in ("sz", "szCs", "highlight"):
            idx = i
    if idx >= 0:
        rpr.insertBefore(u, children(rpr)[idx + 1])
    else:
        rpr.appendChild(u)
    return True


def main():
    doc = parse(DOCXML)
    changed = []
    for p in doc.getElementsByTagName("w:p"):
        text = para_text(p).strip()
        if text in HEADLINES and text not in changed:
            changed.append(text)
            for run in children(p):
                if local(run) == "r" and run_has_text(run):
                    ensure_underline(run)
    if len(changed) != len(HEADLINES):
        print("WARNING: expected %d headlines, found %d" % (len(HEADLINES), len(changed)))
    with open(DOCXML, "w", encoding="ascii") as fh:
        doc.writexml(fh, indent="  ", newl="\n", addindent="  ", encoding="ascii")
    print("Underlined headlines: %d -> %s" % (len(changed), sorted(changed)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

