"""Underline all headline paragraphs in an unpacked DOCX (word/document.xml).

Usage: python underline_headlines.py <unpacked_dir>
"""
import re
import sys
import xml.etree.ElementTree as ET

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def q(tag):
    return "{%s}%s" % (W, tag)

ET.register_namespace("w", W)

# All-caps section headlines present in quarterly_report.docx.
EXPLICIT = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}

HEADING_STYLES = {"Title", "Subtitle", "Heading1", "Heading2", "Heading3",
                  "Heading4", "Heading5", "Heading6", "Heading7", "Heading8",
                  "Heading9"}

# CT_RPr child order so an inserted <w:u> is schema-valid.
RPR_ORDER = ["rStyle", "rFonts", "b", "bCs", "i", "iCs", "caps", "smallCaps",
             "strike", "dstrike", "outline", "shadow", "emboss", "imprint",
             "noProof", "snapToGrid", "vanish", "webHidden", "color", "spacing",
             "w", "kern", "position", "sz", "szCs", "highlight", "u", "effect",
             "bdr", "shd", "fitText", "vertAlign", "rtl", "cs", "em", "lang",
             "eastAsianLayout", "specVanish", "oMath"]


def para_text(p):
    return "".join(t.text or "" for t in p.iter(q("t")))


def looks_like_headline(p):
    ppr = p.find(q("pPr"))
    if ppr is not None:
        if ppr.find(q("outlineLvl")) is not None:
            return True
        ps = ppr.find(q("pStyle"))
        if ps is not None and ps.get(q("val")) in HEADING_STYLES:
            return True
    s = para_text(p).strip()
    if not s or len(s) > 60:
        return False
    if s in EXPLICIT:
        return True
    # Fallback heuristic: uppercase title text, no bullets/box-drawing chars.
    if re.search(r"[a-z]", s) or not re.search(r"[A-Z0-9]", s):
        return False
    if re.search(r"[\u2022\u2500\u2550\u00b7]", s):
        return False
    return True


def ensure_rpr(r):
    rpr = r.find(q("rPr"))
    if rpr is None:
        rpr = ET.Element(q("rPr"))
        r.insert(0, rpr)
    return rpr


def ensure_underline(r):
    rpr = ensure_rpr(r)
    u = rpr.find(q("u"))
    if u is not None:
        if u.get(q("val")) != "single":
            u.set(q("val"), "single")
        return False
    idx = RPR_ORDER.index("u")
    pos = len(rpr)
    for i, child in enumerate(rpr):
        tag = child.tag.split("}")[-1]
        if tag in RPR_ORDER and RPR_ORDER.index(tag) > idx:
            pos = i
            break
    u = ET.Element(q("u"))
    u.set(q("val"), "single")
    rpr.insert(pos, u)
    return True


def main(unpacked_dir):
    path = unpacked_dir.rstrip("/") + "/word/document.xml"
    tree = ET.parse(path)
    root = tree.getroot()
    body = root.find(q("body"))
    if body is None:
        raise SystemExit("no w:body element found in %s" % path)
    changed = []
    for p in body.iter(q("p")):
        if not looks_like_headline(p):
            continue
        label = para_text(p).strip() or "(untitled)"
        changed.append(label)
        for r in p.findall(q("r")):
            ensure_underline(r)
    tree.write(path, encoding="utf-8", xml_declaration=True)
    print("Underlined %d headline(s):" % len(changed))
    for label in changed:
        print(" - %s" % label)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "quarterly_report_unpacked")

