#!/usr/bin/env python3
"""Apply single underlines to every headline paragraph of quarterly_report.docx.

Uses the docx skill's Document library (see .codex/skills/docx/ooxml.md) against
the unpacked OOXML tree. Only paragraphs whose complete text is one of the
report's uppercase section headlines are formatted; body paragraphs, bullets,
table rows, and empty paragraphs are left untouched.
"""
import os
import sys

BASE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(BASE, ".codex", "skills", "docx"))

from scripts.document import Document  # noqa: E402

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

# Headline texts copied verbatim from word/document.xml of quarterly_report.docx.
HEADLINES = [
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
]

UNDERLINE_TAG = '<w:u w:val="single"/>'


def paragraph_plain_text(paragraph):
    """Concatenated <w:t> text of a paragraph (decoded entities)."""
    chunks = []
    for text_node in paragraph.getElementsByTagNameNS(W_NS, "t"):
        for child in text_node.childNodes:
            if child.nodeType == child.TEXT_NODE:
                chunks.append(child.nodeValue)
    return "".join(chunks)


def run_has_text(run):
    for text_node in run.getElementsByTagNameNS(W_NS, "t"):
        for child in text_node.childNodes:
            if child.nodeType == child.TEXT_NODE and child.nodeValue:
                return True
    return False


def with_underline(run_xml):
    """Return run XML identical to input plus one single underline property."""
    if "<w:u " in run_xml:
        return run_xml
    rpr_end = "</w:rPr>"
    if rpr_end in run_xml:
        return run_xml.replace(rpr_end, UNDERLINE_TAG + rpr_end, 1)
    open_end = run_xml.index(">") + 1
    return run_xml[:open_end] + "<w:rPr>" + UNDERLINE_TAG + "</w:rPr>" + run_xml[open_end:]


def main():
    unpacked_dir = sys.argv[1] if len(sys.argv) > 1 else "quarterly_report_ooxml"
    doc = Document(os.path.join(BASE, unpacked_dir))
    xml_editor = doc["word/document.xml"]

    underlined = []
    missing = []

    for headline in HEADLINES:
        paragraph = xml_editor.get_node(tag="w:p", contains=headline)
        if paragraph is None:
            missing.append(headline)
            continue
        if paragraph_plain_text(paragraph).strip() != headline:
            missing.append(headline)
            continue

        runs = [n for n in paragraph.getElementsByTagNameNS(W_NS, "r")
                if run_has_text(n)]
        for run in runs:
            xml_editor.replace_node(run, with_underline(run.toxml()))
        underlined.append(headline)

    doc.save()

    print("Headlines underlined: %d of %d" % (len(underlined), len(HEADLINES)))
    for name in underlined:
        print("  - " + name)
    for name in missing:
        print("  - MISSING/UNCHANGED: " + name, file=sys.stderr)
    return 0 if not missing else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Underline all report headlines in the unpacked quarterly_report.docx OOXML."""

import sys
from pathlib import Path

from defusedxml import minidom

W_MAIN = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

# All-caps section headlines identified in the report body
HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}


def paragraph_text(p):
    """Concatenated visible text of all w:t descendants of a paragraph."""
    return "".join(
        t.firstChild.nodeValue
        for t in p.getElementsByTagName("w:t")
        if t.firstChild and t.firstChild.nodeValue
    )


def underline_paragraph(p, dom):
    """Ensure every run of the paragraph carries single underline formatting."""
    underlined = 0
    for r in p.getElementsByTagName("w:r"):
        rpr = None
        for child in r.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
                rpr = child
                break
        if rpr is None:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        u = None
        for child in rpr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:u":
                u = child
                break
        if u is None:
            u = dom.createElement("w:u")
            rpr.appendChild(u)
        u.setAttribute("w:val", "single")
        underlined += 1
    return underlined


def main(argv):
    unpacked = Path(argv[0]) if argv else Path("quarterly_report_ooxml")
    document_path = unpacked / "word" / "document.xml"

    dom = minidom.parse(str(document_path))
    bodies = dom.getElementsByTagName("w:body")

    matched = []
    total_runs = 0
    for body in bodies:
        for p in body.getElementsByTagName("w:p"):
            text = paragraph_text(p)
            if text in HEADLINES:
                total_runs += underline_paragraph(p, dom)
                matched.append(text)

    with open(document_path, "wb") as f:
        f.write(dom.toprettyxml(indent="  ", encoding="utf-8"))

    print(
        "Underlined {} headline(s) ({} run(s)): {}".format(
            len(matched), total_runs, ", ".join(matched)
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

